const now = new Date();
const lookbackDays = $input.first().json.LOOKBACK_DAYS || 7;
const sinceDate = new Date(now.getTime() - (lookbackDays * 24 * 60 * 60 * 1000));
return {
  json: {
    ...$input.first().json,
    sinceISO: sinceDate.toISOString(),
    formattedDateRange: `${sinceDate.toISOString().slice(0, 10)} to ${now.toISOString().slice(0, 10)}`
  }
};

// Aggregate raw GitHub outputs into structured metadata
const config = $('Config & Environment').first().json;
const dateWindow = $('Calculate Date Window').first().json;
const sinceDate = new Date(dateWindow.sinceISO);

// 1. Commits
let rawCommits = [];
try {
  rawCommits = $('Fetch Weekly Commits').all().map(i => i.json);
} catch (e) {}
const commits = rawCommits.map(c => ({
  sha: c.sha ? c.sha.slice(0, 7) : '',
  message: c.commit ? c.commit.message.split('\n')[0] : '',
  author: c.commit && c.commit.author ? c.commit.author.name : 'Unknown',
  date: c.commit && c.commit.author ? c.commit.author.date : ''
}));

// 2. Merged PRs
let rawPRs = [];
try {
  rawPRs = $('Fetch Closed PRs').all().map(i => i.json);
} catch (e) {}
const mergedPRs = rawPRs.filter(pr => {
  if (!pr.merged_at) return false;
  const mergedDate = new Date(pr.merged_at);
  return mergedDate >= sinceDate;
}).map(pr => ({
  number: pr.number,
  title: pr.title,
  author: pr.user ? pr.user.login : 'unknown',
  merged_at: pr.merged_at,
  labels: (pr.labels || []).map(l => l.name),
  url: pr.html_url
}));

// 3. Closed Issues (excluding PRs)
let rawIssues = [];
try {
  rawIssues = $('Fetch Closed Issues').all().map(i => i.json);
} catch (e) {}
const closedIssues = rawIssues.filter(iss => !iss.pull_request).map(iss => ({
  number: iss.number,
  title: iss.title,
  labels: (iss.labels || []).map(l => l.name),
  url: iss.html_url
}));

// 4. Contributors
const contributors = new Set();
commits.forEach(c => contributors.add(c.author));
mergedPRs.forEach(pr => contributors.add(pr.author));

const language = (config.LANGUAGE || 'EN').toUpperCase();
const languagePrompt = language === 'FR' 
  ? 'Rédige le rapport en français professionnel et engageant.'
  : 'Write the report in clear, concise, professional English.';

const prompt = `You are a Principal Engineering Lead. Generate a high-impact, engaging weekly executive engineering summary based on the following GitHub activity for repository **${config.GITHUB_OWNER}/${config.GITHUB_REPO}** during the period **${dateWindow.formattedDateRange}**.

${languagePrompt}

### Raw Activity Metrics:
- Total Commits: ${commits.length}
- Merged Pull Requests: ${mergedPRs.length}
- Closed Issues: ${closedIssues.length}
- Active Contributors: ${Array.from(contributors).join(', ') || 'None'}

### Merged PRs:
${mergedPRs.map(p => `- #${p.number}: ${p.title} (by @${p.author}) [${p.labels.join(', ')}]`).join('\n') || 'None'}

### Sample Commits:
${commits.slice(0, 15).map(c => `- [${c.sha}] ${c.message} (by ${c.author})`).join('\n') || 'None'}

### Closed Issues:
${closedIssues.map(i => `- #${i.number}: ${i.title}`).join('\n') || 'None'}

### Required Structure:
1. 🚀 **Executive Summary**: 2-3 high-level sentences capturing the major theme/milestones of the week.
2. 🌟 **Key Features & Major PRs**: Bulleted narrative breakdown of what was shipped and business/technical value.
3. 🛠️ **Bug Fixes, Optimizations & Refactoring**: Key stability and performance enhancements.
4. 👥 **Contributor Spotlight**: Warm recognition of active engineers.
5. 🎯 **Looking Ahead**: Next priorities inferred from open context.

Format with crisp Markdown, bold emphasis, and suitable emojis.`;

return {
  json: {
    ...config,
    ...dateWindow,
    stats: {
      commitsCount: commits.length,
      prsCount: mergedPRs.length,
      issuesCount: closedIssues.length,
      contributorsCount: contributors.size
    },
    activitySummaryPrompt: prompt
  }
};

