const claudeResponse = $input.first().json;
const synth = $('Synthesize & Prepare Claude Prompt').first().json;

let narrativeText = '';
if (claudeResponse.content && Array.isArray(claudeResponse.content)) {
  narrativeText = claudeResponse.content.map(c => c.text).join('\n');
} else if (claudeResponse.narrative) {
  narrativeText = claudeResponse.narrative;
} else {
  narrativeText = JSON.stringify(claudeResponse);
}

// Format Discord payload
const discordPayload = {
  content: `📢 **Weekly Engineering Digest: ${synth.GITHUB_OWNER}/${synth.GITHUB_REPO}** (${synth.formattedDateRange})`,
  embeds: [
    {
      title: `Weekly Engineering Report — ${synth.formattedDateRange}`,
      description: narrativeText.length > 3900 ? narrativeText.slice(0, 3900) + '...' : narrativeText,
      color: 5814783,
      fields: [
        { name: 'Merged PRs', value: `${synth.stats.prsCount}`, inline: true },
        { name: 'Commits', value: `${synth.stats.commitsCount}`, inline: true },
        { name: 'Closed Issues', value: `${synth.stats.issuesCount}`, inline: true }
      ],
      footer: {
        text: 'Generated autonomously with Claude Code & n8n'
      }
    }
  ]
};

// Format Slack payload
const slackPayload = {
  blocks: [
    {
      type: 'header',
      text: {
        type: 'plain_text',
        text: `🚀 Weekly Dev Summary: ${synth.GITHUB_OWNER}/${synth.GITHUB_REPO}`,
        emoji: true
      }
    },
    {
      type: 'context',
      elements: [
        {
          type: 'mrkdwn',
          text: `*Date Window:* ${synth.formattedDateRange} | *PRs:* ${synth.stats.prsCount} | *Commits:* ${synth.stats.commitsCount}`
        }
      ]
    },
    {
      type: 'divider'
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: narrativeText.length > 2900 ? narrativeText.slice(0, 2900) + '...' : narrativeText
      }
    }
  ]
};

return {
  json: {
    ...synth,
    narrative: narrativeText,
    discordPayload,
    slackPayload
  }
};
